import PocketBase from 'pocketbase';

// Preview receives an explicit endpoint because its parent is cross-origin.
function getInitialBaseUrl() {
  if (typeof window === 'undefined') return 'http://127.0.0.1:8090';
  try {
    const params = new URLSearchParams(window.location.search);
    const qDb = params.get('pocketapp_db');
    const qOrigin = params.get('pocketapp_origin');
    if (qDb) sessionStorage.setItem('pocketapp_db', qDb);
    if (qOrigin) sessionStorage.setItem('pocketapp_origin', qOrigin);
    const projectId = qDb || sessionStorage.getItem('pocketapp_db');
    const platformOrigin = qOrigin || sessionStorage.getItem('pocketapp_origin');
    if (projectId && platformOrigin) {
      return new URL(platformOrigin).origin + '/api/project-db/' + encodeURIComponent(projectId) + '/data';
    }
  } catch {}
  return import.meta.env.VITE_PB_URL || import.meta.env.VITE_POCKETBASE_URL || window.location.origin;
}

export const pb = new PocketBase(getInitialBaseUrl());
pb.autoCancellation(false);

if (typeof window !== 'undefined') {
  window.addEventListener('message', (event) => {
    if (event.data && event.data.type === 'pocketapp_db_config' && event.data.projectId && event.data.origin) {
      try {
        sessionStorage.setItem('pocketapp_db', event.data.projectId);
        sessionStorage.setItem('pocketapp_origin', event.data.origin);
        pb.baseURL = new URL(event.data.origin).origin + '/api/project-db/' + encodeURIComponent(event.data.projectId) + '/data';
      } catch {}
    }
  });
}
